window.BUILDS=[{"n":1,"slug":"northgate-quote-engine","kind":"tool","group":"Sales tools","name":"Northgate Quote Engine","biz":"Kitchen fitter","short":"A quote that assembles itself while the customer answers.","long":"Nine questions. As the customer answers, an isometric kitchen draws itself — cabinets appear, the worktop changes material, the island slides in — and a sticky panel builds the price live. It ends in an itemised quote that prints to A4.","proves":"Turns a \"can you price this up?\" text into a priced job at midnight.","tags":["Generative SVG","Live pricing","Prints to A4"],"c":"#245247"},{"n":2,"slug":"redgate-job-system","kind":"tool","group":"Sales tools","name":"Redgate Job & Lead System","biz":"Heating & plumbing","short":"Every enquiry, where it came from, and what happened to it.","long":"A pipeline at real product density: drag-and-drop kanban, a sortable table, a deal drawer with the full activity timeline, and a Cmd-K palette that searches deals, contacts and commands.","proves":"Nothing lives in your texts any more.","tags":["Kanban + table","Cmd-K palette","CSV export"],"c":"#3730a3"},{"n":3,"slug":"halcyon-dispatch","kind":"tool","group":"Operations","name":"Halcyon Dispatch","biz":"Heating dispatch team","short":"Drag a job to another engineer and the week re-plans itself.","long":"Week and day scheduling for a field team. Drag to reschedule, clashes and capacity overruns flag instantly, SLA countdowns run against the real clock — so the board reads correctly whatever day you open it.","proves":"Six engineers, one screen, no phone calls to find out who is where.","tags":["Drag to reschedule","Clash detection","SLA countdown"],"c":"#2f5cdb"},{"n":4,"slug":"ledgerline","kind":"tool","group":"Operations","name":"Ledgerline","biz":"Invoice & proposal studio","short":"A live A4 page that reflows as you type.","long":"Invoices and proposals with a real page preview, three templates that genuinely change the layout, money maths done in integer pence, and a print stylesheet that gives you a proper PDF.","proves":"The paperwork stops being a Sunday job.","tags":["Live A4 preview","Aged debt","Print to PDF"],"c":"#1f4fd8"},{"n":5,"slug":"mortgage-lab","kind":"tool","group":"Calculators","name":"Mortgage Lab","biz":"Broker lead magnet","short":"What an overpayment really saves, month by month.","long":"A full amortisation engine behind a scrubber chart. Shows the years and interest an overpayment saves, stress-tests the next remortgage at +1/2/3 points, and compares three saved scenarios side by side.","proves":"The kind of tool people bookmark, then ring you about.","tags":["Amortisation engine","Stress test","Scenarios"],"c":"#0b6e4f"},{"n":6,"slug":"payslip-lab","kind":"tool","group":"Calculators","name":"Payslip Lab","biz":"Accountant lead magnet","short":"Gross to net, and the 60% trap nobody explains.","long":"A UK take-home planner: a waterfall from gross to net, a marginal-rate curve that exposes the taper between £100k and £125,140, and employee vs sole trader vs limited company side by side.","proves":"One page that answers the question every new client opens with.","tags":["Waterfall chart","60% trap curve","Reverse solver"],"c":"#2952cc"},{"n":11,"slug":"kerbside-scorecard","kind":"tool","group":"Winning work","name":"Kerbside Scorecard","biz":"Google profile report card","short":"Marks a Google Business Profile like an exam.","long":"Type a business’s numbers — reviews, photos, categories, map rank — and it grades the profile: per-row deductions, the fix for each one, and what the gap is costing per month. Prints as a client-ready report.","proves":"A prospect sees their own grade before you ever pitch.","tags":["Live re-marking","Competitor table","Prints to A4"],"c":"#B42318"},{"n":12,"slug":"stopcock","kind":"tool","group":"Winning work","name":"Stopcock","biz":"Missed-call leak meter","short":"What unanswered calls cost you a year.","long":"Five sliders — calls, missed share, job value, close rate — and it meters the annual leak, where it goes, and what a 60-second text-back recovers. Every assumption is on show, including a gone-for-good factor, so the number survives a sceptic.","proves":"The maths behind the whole offer, in the prospect’s own numbers.","tags":["Animated meter","Call funnel","Honest model"],"c":"#14606E"},{"n":13,"slug":"turnover","kind":"tool","group":"Winning work","name":"Turnover","biz":"Roofing firm rebuild","short":"Drag the tape line across a 2011 site and its rebuild.","long":"The same roofing firm on both sides of a draggable tape line — the old site on one side, the rebuild on the other — then a table of what actually changed. Both sites are drawn in code, not screenshots.","proves":"“Before and after” you can put your hands on.","tags":["Drag reveal","Phone frame","Change table"],"c":"#C77D2B"},{"n":14,"slug":"fenwick-booking","kind":"tool","group":"Operations","name":"Fenwick Booking","biz":"Heating engineer","short":"Service, slot, deposit, confirmed — no phone tag.","long":"Five steps: pick a service, take a slot from a grid generated off the real calendar, leave details, pay a deposit that holds the slot, and see the SMS trail that follows. Demo payment only — the card fields are fixed test values.","proves":"The job is in the diary before you have picked up the phone.","tags":["Live slot grid","Demo deposit","SMS preview"],"c":"#B4451F"},{"n":15,"slug":"jobsheet","kind":"tool","group":"Operations","name":"Jobsheet","biz":"Van-side job report","short":"Fill it in from the van, the customer report writes itself.","long":"Work done, before/after photos (uploaded and downscaled on your own phone), guarantee, next service due — and out comes a branded report the customer keeps and forwards. The review ask is built into the last page.","proves":"Every finished job leaves a document with your name on it.","tags":["Live report","Photo upload","Prints to A4"],"c":"#275C3F"},{"n":16,"slug":"shiftbook","kind":"tool","group":"Operations","name":"Shiftbook","biz":"Salon staff rota","short":"Click a cell to place a shift. Clashes flag as you go.","long":"Click to roster, clashes flag instantly, hours fill against each contract and run red when over, wage cost totals live at the bottom. Weeks anchor to the real calendar and last week copies in one click.","proves":"The rota stops being a photo of a whiteboard.","tags":["Click to roster","Contract hours","Wage totals"],"c":"#6D3B52"},{"n":7,"slug":"atelier-voss","kind":"site","group":"Websites","name":"Atelier Voss","biz":"Architecture practice","short":"A studio site with no photographs at all.","long":"The entire site is illustrated in hand-authored technical drawings: elevations that draw themselves in, hatched plans, dimension lines, poché section cuts. Cyanotype blue, and a real six-cell title block for a masthead.","proves":"What a site looks like when nothing on it came from a stock library.","tags":["All-SVG drawings","Pinned sequence","Title block"],"c":"#14508c"},{"n":8,"slug":"cadence","kind":"site","group":"Websites","name":"Cadence","biz":"Field-ops software","short":"The page is an operations board that never stops running.","long":"A departure board under tungsten light: the board is the hero, the headline is a card pinned inside it, ETAs flip like split-flap cells, and a whole shift plays out as you scroll. Pricing is a line-items table.","proves":"A product page where the product is the page.","tags":["Self-playing board","Split-flap cells","Signal amber"],"c":"#FFB300"},{"n":9,"slug":"maree","kind":"site","group":"Websites","name":"MARÉE — Sel Obscur","biz":"Fragrance house","short":"Ink through water, and a page that darkens as you descend.","long":"Salt drawn from a black tide. The ground moves through three marine phases as the notes progress, the bottle is faked entirely in layered SVG, and the whole thing refuses the category’s gold for sea glass.","proves":"Luxury without a single gold gradient.","tags":["Ink canvas","Tone-shifting scroll","SVG glass"],"c":"#A9CBBD"},{"n":10,"slug":"signal","kind":"site","group":"Websites","name":"SIGNAL 2027","biz":"Music & light festival","short":"Type that reacts to how hard you scroll.","long":"Three days of sound, code and light. Marquees whose speed and skew answer your scrolling, headlines that scramble into place, an RGB fringe on the display type because the identity is light being split, and a live countdown in enormous tabular numerals.","proves":"Loud, and still not a template.","tags":["Scroll-velocity type","RGB fringe","Live countdown"],"c":"#3B18E0"}];
